#include <stdio.h>

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    unsigned int adj[20] = {0};

    for (int i = 0; i < M; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        --x;
        --y;
        adj[x] |= 1u << y;
        adj[y] |= 1u << x;
    }

    int limit = 1 << N;
    unsigned char independent[1 << 20] = {0};
    independent[0] = 1;

    int count = 0;
    for (int mask = 1; mask < limit; mask++) {
        int bit = mask & -mask;
        int vertex = __builtin_ctz((unsigned int)bit);
        int rest = mask ^ bit;

        if (independent[rest] && !(adj[vertex] & (unsigned int)rest)) {
            independent[mask] = 1;
            count++;
        }
    }

    printf("%d\n", count);
    return 0;
}
